    exports.CubismClippingContext_WebGL = CubismClippingContext_WebGL;
    exports.CubismClippingManager_WebGL = CubismClippingManager_WebGL;
    exports.CubismRendererProfile_WebGL = CubismRendererProfile_WebGL;
